panels.css:
main{padding:0;height:1080px;display:block}
.vsw{position:relative;height:1080px;overflow:hidden;background:radial-gradient(circle at 18% 40%,rgba(255,153,0,.16),transparent 46%),radial-gradient(circle at 84% 62%,rgba(191,0,0,.14),transparent 48%),var(--cream)}
.ttl{padding:58px 64px 0;text-align:center}
.ttl .k{font-size:30px;font-weight:700;color:var(--ink-2)}
.ttl h1{font-size:66px;font-weight:900;line-height:1.2;margin-top:6px;color:var(--ink)}
.ttl h1 em{font-style:normal;color:#fff;background:linear-gradient(90deg,#FF9900,#BF0000);padding:0 18px;border-radius:14px;margin-left:6px}
.cards{position:relative;height:660px;margin-top:44px}
.card{position:absolute;top:0;width:440px;border-radius:34px;padding:34px 34px 30px;color:#fff;box-shadow:0 30px 60px -24px rgba(30,18,25,.55)}
.card.amz{left:60px;background:linear-gradient(160deg,#37475A 0%,#232F3E 60%,#131A22 100%);transform:rotate(-3.5deg);border-bottom:12px solid #FF9900}
.card.rkt{right:60px;top:20px;background:linear-gradient(160deg,#E0201A 0%,#BF0000 55%,#8E0000 100%);transform:rotate(3.5deg);border-bottom:12px solid #fff}
.chip{background:#fff;border-radius:18px;height:84px;display:flex;align-items:center;justify-content:center;padding:10px 20px}
.amz .chip img{height:76px}.rkt .chip img{height:50px}
.tag{font-size:19px;font-weight:700;opacity:.9;margin-top:14px}
.rule{margin-top:6px;font-size:34px;font-weight:900;line-height:1.25}
.rule small{display:block;font-size:22px;font-weight:700;opacity:.8}
.rule b{font-size:58px}
.amz .rule b{color:#FF9900}
.rkt .rule b{color:#FFF1C8}
.rule i{display:block;font-style:normal;font-size:19px;font-weight:700;opacity:.9;margin-top:2px}
.card ul{list-style:none;margin-top:18px;border-top:2px solid rgba(255,255,255,.22)}
.card li{display:flex;justify-content:space-between;align-items:baseline;padding:7px 0;border-bottom:2px solid rgba(255,255,255,.14)}
.card li span{font-size:20px;font-weight:700;opacity:.8}
.card li b{font-size:30px;font-weight:900}
.due{margin-top:18px;display:inline-block;font-size:22px;font-weight:900;padding:8px 16px;border-radius:999px}
.amz .due{background:#FF9900;color:#131A22}
.rkt .due{background:#fff;color:#BF0000}
.vs{position:absolute;left:50%;top:-6px;transform:translateX(-50%);width:132px;height:132px;border-radius:50%;background:var(--ink);color:#F5C518;font-size:52px;font-weight:900;display:flex;align-items:center;justify-content:center;border:8px solid var(--cream);box-shadow:0 14px 30px -10px rgba(0,0,0,.5);z-index:3;font-style:italic}
.foot{position:absolute;left:64px;right:64px;bottom:40px;white-space:nowrap;background:var(--cream-2);border-radius:20px;padding:20px 26px;font-size:27px;font-weight:700;text-align:center}
.foot b{color:var(--pink-700)}
.due{margin-top:20px}
.rkchip{color:#BF0000;font-size:40px;font-weight:900}
.due{font-size:19px}
.cards{height:690px}
.foot{font-size:25px}
.ttl{padding:36px 40px 0}
.ttl .k{font-size:26px}
.ttl h1{font-size:50px;line-height:1.15;margin-top:6px;display:flex;flex-wrap:wrap;justify-content:center;align-items:baseline;gap:4px 14px}
.ttl h1 .ta{color:#232F3E;border-bottom:8px solid #FF9900;padding:0 4px}
.ttl h1 .tr{color:#BF0000;border-bottom:8px solid #BF0000;padding:0 4px}
.ttl h1 .tv{font-size:36px;font-style:italic;color:#7A6A72}
.ttl .ts{font-size:27px;font-weight:800;margin-top:12px;color:var(--ink)}
.ttl .ts em{font-style:normal;color:#fff;background:linear-gradient(90deg,#FF9900,#BF0000);padding:0 10px;border-radius:8px}
.cards{margin-top:26px;height:660px}
.card{transform-origin:center top}
.card.amz{transform:rotate(-3deg) scale(.95)}
.card.rkt{transform:rotate(3deg) scale(.95)}
.foot{bottom:28px}


.tabbn{position:relative;overflow:hidden}
.tabbn .bn{position:absolute;inset:0;background-size:cover;background-position:center 40%;opacity:.38}
.tabbn img{position:relative;z-index:1;background:rgba(255,255,255,.82);border-radius:12px;padding:2px 14px}

.tabbn .bn.bnr{background-size:contain;background-repeat:no-repeat;background-position:center;opacity:.32}
.rkchip b{position:relative;z-index:1;background:rgba(255,255,255,.8);border-radius:12px;padding:0 16px}

main{padding:0;height:1080px;display:block}
.wrap{position:relative;height:1080px;padding:44px 50px 0;background:radial-gradient(circle at 12% 30%,rgba(255,153,0,.13),transparent 45%),radial-gradient(circle at 90% 70%,rgba(191,0,0,.11),transparent 48%),var(--cream)}
.k{font-size:26px;font-weight:700;color:var(--ink-2);text-align:center}
.t{font-size:50px;font-weight:900;line-height:1.25;text-align:center;margin-top:4px}
.t em{font-style:normal;color:#BF0000}
.t b{color:#E47911}
.sub{text-align:center;font-size:21px;color:var(--ink-2);font-weight:700;margin-top:8px}
.note{position:absolute;left:50px;right:50px;bottom:30px;font-size:19px;line-height:1.5}

.board{margin-top:22px;background:#fff;border-radius:26px;box-shadow:0 26px 50px -26px rgba(30,18,25,.45);overflow:hidden}
.board .hd,.board .row{display:grid;grid-template-columns:1.35fr 1fr 1fr 1fr;align-items:center}
.board .hd span{height:84px;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:26px;font-weight:900;line-height:1.1}
.board .hd span small{font-size:17px;font-weight:700;opacity:.9;margin-top:4px}
.board .hd .ha{background:#232F3E;border-bottom:6px solid #FF9900}
.board .hd .ha img{height:46px;background:#fff;border-radius:10px;padding:4px 12px}
.board .hd .hr{background:#BF0000;color:#fff;border-bottom:6px solid #8E0000}
.board .hd .hr2{background:#F3D5D5;color:#8E0000;border-bottom:6px solid #BF0000}
.board .row{border-top:2px solid var(--line);min-height:86px}
.nm{padding:0 18px;font-size:24px;font-weight:900;line-height:1.2}
.nm small{display:block;font-size:15px;font-weight:700;color:var(--ink-2)}
.v{text-align:center;font-size:27px;font-weight:900;color:var(--ink-2);height:100%;display:flex;align-items:center;justify-content:center}
.v.win.a{background:#232F3E;color:#fff}.v.half{background:#FFE7C2;color:#7A4100}
.v.win.r{background:#BF0000;color:#fff}

.note{font-size:17px;line-height:1.5;padding:14px 20px}

main{padding:0;height:1080px;display:block}
.wrap{position:relative;height:1080px;padding:44px 50px 0;background:radial-gradient(circle at 12% 30%,rgba(255,153,0,.13),transparent 45%),radial-gradient(circle at 90% 70%,rgba(191,0,0,.11),transparent 48%),var(--cream)}
.k{font-size:26px;font-weight:700;color:var(--ink-2);text-align:center}
.t{font-size:50px;font-weight:900;line-height:1.25;text-align:center;margin-top:4px}
.t em{font-style:normal;color:#BF0000}
.t b{color:#E47911}
.sub{text-align:center;font-size:21px;color:var(--ink-2);font-weight:700;margin-top:8px}
.note{position:absolute;left:50px;right:50px;bottom:30px;font-size:19px;line-height:1.5}

.tri{display:grid;grid-template-columns:1fr 1fr 1fr;gap:18px;margin-top:30px}
.c{border-radius:26px;padding:20px 20px;background:#fff;border:3px solid var(--line);box-shadow:0 20px 40px -26px rgba(30,18,25,.4)}
.c.win{border:6px solid #BF0000}
.lg{height:64px;display:flex;align-items:center;justify-content:center;border-radius:14px}
.c.a .lg{background:#232F3E}.c.a .lg img{height:48px;background:#fff;border-radius:10px;padding:4px 12px}
.rkl{background:#BF0000;color:#fff;font-size:28px;font-weight:900}
.rkl2{background:#F3D5D5;color:#8E0000;font-size:28px;font-weight:900}
.who{text-align:center;font-size:21px;font-weight:900;margin:10px 0 2px}
.ln,.net{display:flex;justify-content:space-between;align-items:baseline;padding:14px 2px;border-top:2px solid var(--line)}
.ln span,.net span{font-size:18px;font-weight:700;color:var(--ink-2)}
.ln b{font-size:30px;font-weight:900}
.net{flex-direction:column;align-items:flex-start;gap:4px}
.net b{font-size:42px;font-weight:900}
.c.win .net b{color:#BF0000}
.diff{margin-top:34px;text-align:center;font-size:31px;font-weight:900;line-height:1.6}
.diff em{font-style:normal;background:#F3D5D5;color:#8E0000;padding:2px 12px;border-radius:10px}
.diff em.a{background:#FFE7C2;color:#7A4100}
.note{font-size:20px}

