.wrap{position:relative;height:1080px;padding:54px 60px 0;background:radial-gradient(circle at 12% 30%,rgba(255,153,0,.13),transparent 45%),radial-gradient(circle at 90% 70%,rgba(191,0,0,.11),transparent 48%),var(--cream)}
.k{font-size:28px;font-weight:700;color:var(--ink-2);text-align:center}
.t{font-size:56px;font-weight:900;line-height:1.25;text-align:center;margin-top:6px}
.t em{font-style:normal;color:#BF0000}
.t b{color:#E47911}
.sub{text-align:center;font-size:23px;color:var(--ink-2);font-weight:700;margin-top:10px}
.amzc{color:#E47911}.rk{color:#BF0000;font-weight:900}
.note{position:absolute;left:60px;right:60px;bottom:44px;font-size:24px}

.t{font-size:46px;white-space:nowrap}
.steps2{display:flex;flex-direction:column;gap:34px;margin-top:56px}
.s{display:flex;gap:28px;align-items:center;background:#fff;border-radius:28px;padding:44px 34px;box-shadow:0 20px 40px -26px rgba(30,18,25,.4)}
.s.a{border-left:14px solid #FF9900}.s.r{border-left:14px solid #BF0000}
.s .lg{flex:0 0 210px;height:96px;display:flex;align-items:center;justify-content:center;border-radius:18px}
.s.a .lg{background:#232F3E}.s.a .lg img{height:64px;background:#fff;border-radius:12px;padding:4px 14px}
.s .rkl{background:#BF0000;color:#fff;font-size:36px;font-weight:900}
.tx b{display:block;font-size:34px;font-weight:900;line-height:1.35}
.tx span{display:block;font-size:26px;font-weight:600;color:var(--ink-2);line-height:1.6;margin-top:8px}
